def parse_json(s):
    def skip_whitespace():
        nonlocal i
        while i < len(s) and s[i] in ' \t\n\r':
            i += 1

    def parse_value():
        nonlocal i
        skip_whitespace()
        if i >= len(s):
            return None
        c = s[i]
        if c == '"': return parse_string()
        if c == '{': return parse_object()
        if c == '[': return parse_array()
        if c == 't':
            i += 4; return True
        if c == 'f':
            i += 5; return False
        if c == 'n':
            i += 4; return None
        return parse_number()

    def parse_string():
        nonlocal i
        i += 1
        start = i
        while i < len(s) and s[i] != '"':
            if s[i] == '\\': i += 2
            else: i += 1
        result = s[start:i]
        i += 1
        return result

    def parse_number():
        nonlocal i
        start = i
        if s[i] == '-': i += 1
        while i < len(s) and (s[i].isdigit() or s[i] == '.'):
            i += 1
        val = s[start:i]
        return int(val) if '.' not in val else float(val)

    def parse_array():
        nonlocal i
        i += 1
        result = []
        skip_whitespace()
        if i < len(s) and s[i] == ']':
            i += 1
            return result
        while True:
            result.append(parse_value())
            skip_whitespace()
            if i < len(s) and s[i] == ']':
                i += 1
                break
            i += 1
        return result

    def parse_object():
        nonlocal i
        i += 1
        result = {}
        skip_whitespace()
        if i < len(s) and s[i] == '}':
            i += 1
            return result
        while True:
            skip_whitespace()
            key = parse_string()
            skip_whitespace()
            i += 1
            val = parse_value()
            result[key] = val
            skip_whitespace()
            if i < len(s) and s[i] == '}':
                i += 1
                break
            i += 1
        return result

    i = 0
    return parse_value()
